insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-000000000021', 'en', null, 'Personal Health & First Aid', 'A high-level introduction to staying healthy and understanding basic first aid, built from openly-licensed Health & First Aid material on OER Commons (CC BY). This course is education only — it is not a substitute for hands-on certified training or for professional medical care. In any real emergency, call your local emergency number and seek qualified help.', null, 'daily_life', 33, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000021', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The single most important first step when you find someone hurt is to…","options":["give them water","check that the scene is safe for you","move them to a bed","post about it online"],"answer":1,"explanation":"You cannot help if you also become a casualty — ''Danger'' is the first letter of DR ABC. This course teaches concepts, not a substitute for certified training."},{"prompt":"The letters DR ABC in first aid stand for Danger, Response, and then…","options":["Airway, Breathing, Circulation","Ask, Bandage, Call","Adrenaline, Blood, CPR","Alert, Breathe, Comfort"],"answer":0,"explanation":"DR ABC = Danger, Response, Airway, Breathing, Circulation — a widely taught way to remember priorities."},{"prompt":"For most healthy adults, a reasonable general guideline for nightly sleep is about…","options":["3–4 hours","7–9 hours","12–14 hours","sleep is optional"],"answer":1,"explanation":"Public-health guidance commonly cites roughly 7–9 hours for adults; individual needs vary."},{"prompt":"To stop bleeding from a cut, the first thing to try is usually…","options":["firm direct pressure on the wound","rubbing the wound","raising your voice","waiting for it to stop on its own"],"answer":0,"explanation":"Direct pressure is the standard first response for bleeding. Always seek professional care for serious wounds."},{"prompt":"You should call your local emergency number when someone…","options":["has a mild headache","is unresponsive or not breathing normally","feels a little tired","stubbed a toe"],"answer":1,"explanation":"Unresponsiveness or abnormal breathing is a clear emergency. When in doubt, call."},{"prompt":"''Prevention'' in personal health mostly means…","options":["treating illness after it happens","habits that lower the chance of getting sick","avoiding all doctors","taking any pill you find"],"answer":1,"explanation":"Prevention is about everyday habits — handwashing, sleep, activity — that reduce risk."},{"prompt":"A helpful first response when a friend is very stressed is to…","options":["tell them to just get over it","listen calmly and take their feelings seriously","ignore it","diagnose their condition yourself"],"answer":1,"explanation":"Listening without judgment is a core idea in mental-health first aid; leave diagnosis to professionals."},{"prompt":"This course can best be described as…","options":["a certified first-aid qualification","medical advice for emergencies","an educational overview that encourages proper training","a replacement for calling for help"],"answer":2,"explanation":"It is an overview only. For real skills, take a hands-on course (for example with the Red Cross) and always call professionals in an emergency."}]}'::jsonb, null, 10),
  (2, 'Staying healthy: the everyday basics', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the main pillars of everyday health — food, movement, and sleep — and explain why they matter at a high level. Warm-up: from the diagnostic, roughly how many hours of sleep do most adults need?"},{"heading":"The idea","text":"Good health rests on a few simple, repeatable habits rather than any single trick. A *balanced* diet means eating a variety of foods — plenty of vegetables, fruit, and water, with less added sugar and heavily processed food. *Physical activity* keeps the heart, muscles, and mood strong; public-health bodies often suggest most adults aim for regular moderate movement across the week. *Sleep* is when the body repairs itself, and most adults do best on roughly seven to nine hours. This is general education, not a personalized plan — a doctor or registered dietitian can advise on your specific needs."},{"heading":"Worked example","text":"Imagine mapping one ordinary day. Breakfast includes fruit and water instead of a sugary drink; a twenty-minute walk replaces one short car trip; screens go off a little earlier so lights-out lands near a consistent time. None of these is dramatic, yet together they nudge the day toward the healthy end without any special equipment or expense."},{"heading":"Your turn","text":"For each habit, decide whether it supports or works against the basics: (1) drinking water with meals, (2) scrolling in bed past 1 a.m. every night, (3) taking the stairs when you can, (4) skipping meals then eating one very large late one. Answers: (1) supports — hydration; (2) works against — it erodes sleep; (3) supports — everyday movement; (4) works against — irregular fuelling makes energy and hunger harder to manage."},{"heading":"Common mistakes & exit ticket","text":"Mistake: chasing extreme diets or workout fads instead of steady habits. Mistake: treating one healthy day as a fix — consistency is what counts, and lasting change is easier with professional guidance. Exit: (a) Name the three health pillars in this lesson. (b) True or false: one perfect day matters more than a steady routine. Answers: food/nutrition, physical activity, and sleep; false — the routine matters more."}]}'::jsonb, 'Think in habits, not perfection — small daily choices add up.', 12),
  (3, 'Recognizing an emergency and calling for help', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Recognize signs that a situation is a real emergency and know how to call for help clearly. Warm-up: what is the very first thing you check before approaching someone who is hurt?"},{"heading":"The idea","text":"An emergency is any situation where someone''s life or long-term health may be at serious risk. Warning signs taught in first-aid courses include a person who is *unresponsive*, who is *not breathing normally*, who has severe bleeding that will not stop, who shows signs of a possible heart attack or stroke, or who is choking and cannot speak or cough. In these cases you call your local emergency number (such as 911 in the US, 112 across much of Europe, or 999 in the UK) without delay. This lesson helps you recognize and report — it does not train you to treat; certified courses and professionals do that."},{"heading":"Worked example","text":"Suppose you find a coworker slumped and unresponsive. First you check for *danger* — no traffic, no live wires, no fire — then you try to get a *response* by speaking loudly and gently tapping their shoulders. There is no response, so you (or a bystander you point to directly) call the emergency number, put the phone on speaker, and answer the dispatcher''s questions. The dispatcher can guide you step by step until trained help arrives."},{"heading":"Your turn","text":"Emergency — call now, or not an emergency? (1) a friend is choking and cannot make any sound, (2) a small paper cut, (3) sudden face drooping and slurred speech, (4) mild seasonal sniffles. Answers: (1) emergency — call; (2) not an emergency; (3) emergency — possible stroke, call now; (4) not an emergency, ordinary care is enough."},{"heading":"Common mistakes & exit ticket","text":"Mistake: waiting to ''see if it gets better'' when someone is unresponsive or struggling to breathe — early calls save lives. Mistake: shouting ''someone call for help'' to a crowd; instead point to one specific person and ask them directly. Exit: (a) Name two signs that clearly mean ''call now.'' (b) Why point to one person rather than the whole group? Answers: for example unresponsiveness and not breathing normally; naming one person removes the ''someone else will do it'' effect so the call actually gets made."}]}'::jsonb, 'When in doubt, call — it is always better to ask for help early.', 12),
  (4, 'Basic first aid concepts: bleeding, burns, choking', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe, at a conceptual level, the widely taught first responses to bleeding, burns, and choking. Warm-up: what do the letters DR ABC help you remember?"},{"heading":"The idea","text":"First aid follows priorities. *DR ABC* — Danger, Response, Airway, Breathing, Circulation — reminds you to make the scene safe, check if the person responds, and make sure they can breathe before smaller concerns. For heavy *bleeding*, the standard concept is firm *direct pressure* on the wound with a clean cloth. For minor *burns*, the common guidance is to cool the area under cool running water for several minutes and cover it loosely; never apply ice, butter, or creams. For *choking* in a responsive adult who cannot breathe, cough, or speak, trained responders alternate back blows and abdominal thrusts — but the specific technique must be learned hands-on in a certified course, not from reading. These are concepts to build awareness, not step-by-step medical instructions."},{"heading":"Worked example","text":"Picture a kitchen scene. Someone touches a hot pan and gets a small burn. The concept in action: move away from the heat source (Danger), check they are okay and talking (Response), then hold the area under cool running water while someone gathers more information. Separately, if a person at the table suddenly clutches their throat and cannot make a sound, that points toward choking — a bystander trained in the technique would act while another calls the emergency number. The scene shows the order of thinking, not a licence to perform techniques you have not been trained in."},{"heading":"Your turn","text":"Match the situation to the right general concept: (1) a deep cut bleeding steadily, (2) a minor burn from a kettle, (3) someone who cannot breathe, speak, or cough. Options: cool under running water / firm direct pressure and get help / trained choking response and call for help. Answers: (1) firm direct pressure and get help; (2) cool under running water; (3) trained choking response and call for help."},{"heading":"Common mistakes & exit ticket","text":"Mistake: putting ice, butter, or toothpaste on a burn — cool running water is the taught approach. Mistake: believing you can safely perform choking or wound techniques from a written description alone; these require hands-on certified practice. Exit: (a) What does the first ''D'' in DR ABC stand for? (b) What is the common first step for a minor burn? Answers: Danger — make the scene safe; cool it under cool running water and cover loosely, then seek care if needed."}]}'::jsonb, 'DR ABC first — check Danger and Response before anything else.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Before helping an injured person, you should first…","options":["check the scene is safe","give them food","start treatment immediately","take a photo"],"answer":0,"explanation":"''Danger'' comes first in DR ABC — protect yourself so you can help."},{"prompt":"For heavy bleeding, the widely taught first response is…","options":["firm direct pressure with a clean cloth","pour cold water over it","shake the limb","ignore it"],"answer":0,"explanation":"Direct pressure is the standard concept; serious wounds still need professional care."},{"prompt":"The common first step for a minor burn is to…","options":["apply butter","cool under cool running water","rub with ice for 20 minutes","cover tightly with tape"],"answer":1,"explanation":"Cool running water; avoid ice, butter, and creams."},{"prompt":"You find someone unresponsive and not breathing normally. You should…","options":["wait and watch","call the emergency number right away","give them a drink","leave to find a doctor yourself"],"answer":1,"explanation":"This is a clear emergency — call immediately or direct a specific person to call."},{"prompt":"Most adults do best on roughly how much sleep?","options":["2–3 hours","7–9 hours","12+ hours","it doesn''t matter"],"answer":1,"explanation":"Around 7–9 hours is the common general guideline; needs vary."},{"prompt":"This course''s guidance on techniques like choking response is that you should…","options":["perform them from memory of this reading","take a certified hands-on course to learn them","never help anyone","only read about them forever"],"answer":1,"explanation":"Concepts here build awareness; real skills come from certified training such as the Red Cross."}]}'::jsonb, null, 8),
  (6, 'CPR basics as a concept', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what CPR is, when it is used, and why proper training matters — at a conceptual level only. Warm-up: which letter in DR ABC points to whether the person is breathing?"},{"heading":"The idea","text":"*CPR* stands for cardiopulmonary resuscitation. It is used when a person is unresponsive and not breathing normally, meaning their heart may have stopped circulating blood. The core idea taught in certified courses is to keep blood and oxygen moving to the brain until professional help arrives, using chest compressions and, when trained, rescue breaths. Many programs also teach how an *AED* (automated external defibrillator) — a device found in many public places — talks a user through each step. Crucially, CPR is a physical skill with specific technique for hand position, depth, and rate; it cannot be learned safely from text. This lesson exists so you recognize the term and the situation, then seek real training."},{"heading":"Worked example","text":"Consider the chain of survival that first-aid programs describe: someone recognizes the emergency and calls for help, trained bystanders begin CPR early, an AED is used if available, and professional responders take over. Each link buys time. The lesson here is the *sequence and the urgency* — call early, start trained help early — not any instruction for you to perform compressions from this page."},{"heading":"Your turn","text":"True or false: (1) CPR is meant for a person who is awake and talking. (2) An AED is designed to guide an untrained bystander with spoken prompts. (3) You can fully learn correct CPR technique by reading a paragraph. Answers: (1) false — it is for someone unresponsive and not breathing normally; (2) true — AEDs give step-by-step audio prompts; (3) false — technique requires hands-on certified practice."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming you must be a medical professional to ever help — bystanders trained in a short course play a vital role, and dispatchers can coach callers. Mistake: thinking reading about CPR replaces practice on a manikin. Exit: (a) In one phrase, when is CPR used? (b) What everyday device can guide a rescuer with voice prompts? Answers: when someone is unresponsive and not breathing normally; an AED. Please take a certified course to actually learn CPR."}]}'::jsonb, 'CPR is a hands-on skill — this lesson explains what it is, not how to perform it.', 12),
  (7, 'Common illnesses and prevention', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe simple, evidence-based habits that lower the risk of common illnesses. Warm-up: name one everyday habit that helps stop germs from spreading."},{"heading":"The idea","text":"Many common illnesses — colds, flu, and stomach bugs — spread through germs we pass by hand, cough, and shared surfaces. *Prevention* leans on a handful of reliable habits: washing hands well with soap and water, covering coughs and sneezes, staying home when contagious, and keeping recommended vaccinations up to date as advised by a healthcare professional. General wellness habits from earlier lessons — good sleep, balanced food, and activity — also help the body''s defenses. This is public-health education; decisions about vaccines, medicines, or specific symptoms belong with a qualified clinician, and this course never gives dosages or diagnoses."},{"heading":"Worked example","text":"Think about the path a cold takes through a household. One person sneezes into their hand and then opens the fridge; the next person touches the same handle and then rubs their eyes. Breaking any link — sneezing into the elbow, washing hands before shared spaces, wiping common surfaces — lowers the chance the germ completes its journey. Prevention is really about quietly removing these links before anyone gets sick."},{"heading":"Your turn","text":"Does the habit help prevent illness or not? (1) washing hands before eating, (2) sharing a water bottle with someone who is sick, (3) covering a cough with your elbow, (4) going to work with a fever that spreads easily. Answers: (1) helps; (2) does not — it spreads germs; (3) helps; (4) does not — resting at home protects others."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reaching for antibiotics for a common cold — colds are usually viral, and only a professional should decide on any medicine. Mistake: treating handwashing as optional. Exit: (a) Name two habits that reduce the spread of germs. (b) True or false: you should self-prescribe medicine based on this lesson. Answers: for example handwashing and covering coughs; false — always consult a healthcare professional."}]}'::jsonb, 'Prevention is cheaper and easier than cure — habits beat heroics.', 11),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"DR ABC","translation":"a memory aid for first-aid priorities: Danger, Response, Airway, Breathing, Circulation","example":"Running through DR ABC reminds you to make the scene safe before anything else."},{"term":"CPR","translation":"cardiopulmonary resuscitation, used when someone is unresponsive and not breathing normally — a skill learned through certified training","example":"The class explained what CPR is, then urged everyone to take a hands-on course to learn it."},{"term":"AED","translation":"automated external defibrillator, a device in many public places that guides a rescuer with spoken prompts","example":"The mall''s AED gave step-by-step voice instructions until paramedics arrived."},{"term":"direct pressure","translation":"pressing firmly on a wound with a clean cloth to help slow bleeding","example":"The taught first response to heavy bleeding is firm direct pressure while getting help."},{"term":"prevention","translation":"everyday habits that lower the chance of getting sick or hurt","example":"Handwashing is simple prevention that breaks the chain of infection."},{"term":"mental-health first aid","translation":"offering calm, non-judgmental support to someone in distress and helping them reach professional help","example":"Mental-health first aid is about listening and connecting people to care, not diagnosing them."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"CPR is appropriate when a person is…","options":["awake and chatting","unresponsive and not breathing normally","slightly tired","hungry"],"answer":1,"explanation":"CPR is for someone unresponsive and not breathing normally — learn it in a certified course."},{"prompt":"An AED is best described as a device that…","options":["diagnoses illness","guides a rescuer with spoken prompts","replaces calling for help","is only for doctors"],"answer":1,"explanation":"AEDs give step-by-step audio guidance and are found in many public places."},{"prompt":"Which habit most directly reduces the spread of germs?","options":["skipping sleep","washing hands with soap and water","sharing drinks when sick","ignoring coughs"],"answer":1,"explanation":"Handwashing breaks the chain of infection."},{"prompt":"A friend seems very stressed and overwhelmed. A good first step is to…","options":["diagnose their disorder","listen calmly and encourage professional support","tell them to toughen up","avoid them"],"answer":1,"explanation":"Mental-health first aid centers on calm listening and connecting people to real help."},{"prompt":"Common colds are usually caused by viruses, so…","options":["antibiotics always cure them fast","only a professional should decide on any medicine","you should share medicine with friends","you never need rest"],"answer":1,"explanation":"Antibiotics target bacteria, not viruses; leave medicine decisions to a clinician."},{"prompt":"The safest way to actually learn first-aid and CPR technique is to…","options":["read summaries like this one only","take a certified hands-on course","watch one short clip once","guess in the moment"],"answer":1,"explanation":"Certified hands-on training (for example with the Red Cross) builds real, safe skills."}]}'::jsonb, null, 8),
  (10, 'Applied project: build a home emergency & first-aid plan', 'writing', '{"sections":[{"heading":"The task","text":"Design a simple written emergency-and-first-aid plan for your home or household. You will not perform any medical procedure — you are planning and preparing so that, if something happens, you can stay calm, keep people safe, and reach professional help quickly. Treat this as an educational planning exercise, not medical advice."},{"heading":"Milestones","text":"1) Write down your local emergency number and your home address exactly as you would tell a dispatcher. 2) List where a basic first-aid kit is kept and three items to check are stocked (for example clean dressings, adhesive bandages, and disposable gloves). 3) Note the location of the nearest AED you know of, such as at a school, gym, or mall. 4) Write two or three lines on how you''d handle a scene using DR ABC thinking — make it safe, check response, then call for help. 5) Add a reminder to book a certified first-aid or CPR course, and note the name of one provider you could contact."},{"heading":"Self-check rubric","text":"✔ Your emergency number and address are written clearly enough to read aloud under stress. ✔ Your kit location and stock list are specific, not vague. ✔ You identified at least one nearby AED or noted that you''ll look for one. ✔ Your plan leads with safety and calling for help rather than attempting techniques you haven''t been trained in. ✔ You committed to real, certified training. If all five are true, you''ve built a responsible plan — now go take that hands-on course, and remember that in any real emergency you call the professionals first."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000021' and l.position = v.pos
);
